-- +goose Up
-- Merged MML device information regroup seed updates (originally 000004..000007).

-- -----------------------------------------------------------------------------
-- Source: 000004_normalize_mml_lte_nr_group_names.sql
-- -----------------------------------------------------------------------------
-- Normalize remaining MML chapter/group display names against CMCC southbound data models.
--
-- Rule:
--   * LTE/NR shared business domains use one unified display name.
--   * Single-technology-only domains keep the southbound directory name.
--   * SA/SB/SC/SD/SE/SF/SF_NR were already handled earlier; this seed starts from SG.

WITH desired(chapter_code, group_code, group_name_zh, group_name_en, display_order) AS (
  VALUES
    ('SG', 'chapter:SG', 'SCTP参数管理', 'SCTP Parameters', 7),
    ('SH', 'chapter:SH', 'RAN协议栈参数', 'RAN Protocol Stack Parameters', 8),
    ('SI', 'chapter:SI', '邻区参数管理', 'Neighbor Cell Parameters', 9),
    ('SJ', 'chapter:SJ', '移动性参数管理', 'Mobility Parameters', 10),
    ('SK', 'chapter:SK', 'SON参数管理', 'SON Parameters', 11),
    ('SL', 'chapter:SL', 'WAN口配置参数管理', 'WAN Port Configuration Parameters', 12),
    ('SM', 'chapter:SM', 'IPsec参数管理', 'IPsec Parameters', 13),
    ('SN', 'chapter:SN', '时间服务器参数管理', 'Time Server Parameters', 14),
    ('SO', 'chapter:SO', 'GPS信息参数管理', 'GPS Information Parameters', 15),
    ('SP', 'chapter:SP', 'MR参数管理', 'Measurement Report Parameters', 16),
    ('SQ', 'chapter:SQ', '性能参数管理', 'Performance Parameters', 17),
    ('SR', 'chapter:SR', '扩展型一体化皮基站参数', 'Extended Integrated Picocell Parameters', 18),
    ('SH_NR', 'chapter:SH_NR', '本地分流规则', 'Local Breakout Rules', 19),
    ('SI_NR', 'chapter:SI_NR', '基站能力参数管理', 'Base Station Capability Parameters', 20),
    ('ST_NR', 'chapter:ST_NR', '软采规则', 'Soft Collection Rules', 21)
)
UPDATE public.mml_command_groups g
SET group_name_zh = d.group_name_zh,
    group_name_en = d.group_name_en,
    name_i18n = jsonb_build_object('zh-CN', d.group_name_zh, 'en-US', d.group_name_en),
    display_order = d.display_order,
    updated_at = now()
FROM desired d
WHERE g.param_version = 'cmcc-td-lte-v2.3'
  AND g.source = 'standard'
  AND g.chapter_code = d.chapter_code
  AND g.group_code = d.group_code
  AND g.deleted_at IS NULL
  AND g.deprecated_at IS NULL;

