    ('SP', 'MOD MR_MGMT_CONFIG', 'Device.FAP.MRMgmt.Config.{i}.Vendor')
), deleted AS (
  DELETE FROM public.mml_command_sub_fields csf
  USING remove_bindings rb, public.mml_commands c, public.mml_command_groups g, public.standard_params sp
  WHERE c.command_code = rb.command_code
    AND c.group_id = g.id
    AND g.chapter_code = rb.chapter_code
    AND g.source = 'standard'
    AND sp.standard_path = rb.standard_path
    AND csf.command_id = c.id
    AND csf.standard_path_id = sp.id
  RETURNING csf.command_id
), affected AS (
  SELECT DISTINCT command_id AS id FROM deleted
)
UPDATE public.mml_commands c
SET target_paths = CASE
      WHEN c.operation_type IN ('ADD', 'RMV') AND COALESCE(c.target_object, '') <> ''
        THEN jsonb_build_array(c.target_object)
      ELSE COALESCE(paths.paths, '[]'::jsonb)
    END,
    tree_node_refs = CASE
      WHEN c.operation_type IN ('ADD', 'RMV') AND COALESCE(c.target_object, '') <> ''
        THEN jsonb_build_array(c.target_object)
      ELSE COALESCE(paths.paths, '[]'::jsonb)
    END,
    updated_at = now()
FROM affected a
LEFT JOIN LATERAL (
  SELECT jsonb_agg(sp.standard_path ORDER BY csf.sort_order, sp.standard_path) AS paths
  FROM public.mml_command_sub_fields csf
  JOIN public.standard_params sp ON sp.id = csf.standard_path_id
  WHERE csf.command_id = a.id
    AND csf.deprecated_at IS NULL
) paths ON true
WHERE c.id = a.id;

WITH remaining_commands AS (
  SELECT c.id
  FROM public.mml_command_groups g
  JOIN public.mml_commands c ON c.group_id = g.id
  WHERE g.source = 'standard'
    AND g.chapter_code IN ('SG','SH','SI','SJ','SK','SL','SM','SN','SO','SP','SQ','SR','SH_NR','SI_NR','ST_NR')
    AND g.deleted_at IS NULL
    AND g.deprecated_at IS NULL
    AND c.deprecated_at IS NULL
)
UPDATE public.mml_commands c
SET target_paths = CASE
      WHEN c.operation_type IN ('ADD', 'RMV') AND COALESCE(c.target_object, '') <> ''
        THEN jsonb_build_array(c.target_object)
      ELSE COALESCE(paths.paths, '[]'::jsonb)
    END,
    tree_node_refs = CASE
      WHEN c.operation_type IN ('ADD', 'RMV') AND COALESCE(c.target_object, '') <> ''
        THEN jsonb_build_array(c.target_object)
      ELSE COALESCE(paths.paths, '[]'::jsonb)
    END,
    updated_at = now()
FROM remaining_commands rc
LEFT JOIN LATERAL (
  SELECT jsonb_agg(sp.standard_path ORDER BY csf.sort_order, sp.standard_path) AS paths
  FROM public.mml_command_sub_fields csf
  JOIN public.standard_params sp ON sp.id = csf.standard_path_id
  WHERE csf.command_id = rc.id
    AND csf.deprecated_at IS NULL
) paths ON true
WHERE c.id = rc.id;


