SELECT group_code, group_name_zh, group_name_en, jsonb_build_object('zh-CN', group_name_zh, 'en-US', group_name_en), replace(group_code, ':', '_')::ltree, 'cmcc-td-lte-v2.3', display_order, 'standard', true, chapter_code, 0, ARRAY[]::text[] FROM desired_groups
ON CONFLICT (param_version, group_code) DO UPDATE SET group_name_zh=EXCLUDED.group_name_zh, group_name_en=EXCLUDED.group_name_en, name_i18n=EXCLUDED.name_i18n, display_order=EXCLUDED.display_order, source=EXCLUDED.source, catalog_protected=EXCLUDED.catalog_protected, chapter_code=EXCLUDED.chapter_code, deprecated_at=NULL, deleted_at=NULL, updated_at=now();

