INSERT INTO public.standard_params (standard_path, entry_type, access, data_type, change_applies, description)
SELECT standard_path, 'parameter', access, data_type, 'Immediate', description FROM upsert_params
ON CONFLICT (standard_path) DO UPDATE SET access=EXCLUDED.access, data_type=EXCLUDED.data_type, change_applies=EXCLUDED.change_applies, description=COALESCE(NULLIF(EXCLUDED.description,''), standard_params.description), updated_at=now();

