UPDATE public.mml_commands c
SET deprecated_at = COALESCE(c.deprecated_at, now()), updated_at = now()
FROM public.mml_command_groups g
WHERE c.group_id = g.id AND g.source='standard' AND g.chapter_code IN (SELECT chapter_code FROM target_groups) AND c.source='standard' AND NOT EXISTS (SELECT 1 FROM canonical k WHERE k.command_code=c.command_code);

