INSERT INTO public.mml_commands (command_name, command_code, category, description, rpc_method, operation_type, target_paths, tree_node_refs, group_id, command_name_i18n, logical_name_i18n, source, catalog_protected, help_doc)
SELECT c.command_name, c.command_code, 'MML', c.command_name, CASE WHEN c.operation_type='MOD' THEN 'SetParameterValues' ELSE 'GetParameterValues' END, c.operation_type, '[]'::jsonb, '[]'::jsonb, g.id, jsonb_build_object('zh-CN', c.command_name, 'en-US', c.command_code), jsonb_build_object('zh-CN', c.logical_name, 'en-US', c.command_code), 'standard', true, ''
FROM cmd_defs c JOIN public.mml_command_groups g ON g.group_code=c.group_code AND g.param_version='cmcc-td-lte-v2.3'
ON CONFLICT (command_code) DO UPDATE SET command_name=EXCLUDED.command_name, description=EXCLUDED.description, rpc_method=EXCLUDED.rpc_method, operation_type=EXCLUDED.operation_type, group_id=EXCLUDED.group_id, command_name_i18n=EXCLUDED.command_name_i18n, logical_name_i18n=EXCLUDED.logical_name_i18n, source=EXCLUDED.source, catalog_protected=EXCLUDED.catalog_protected, deprecated_at=NULL, updated_at=now();

