FROM canonical ca LEFT JOIN LATERAL (SELECT jsonb_agg(sp.standard_path ORDER BY csf.sort_order, sp.standard_path) AS paths FROM public.mml_command_sub_fields csf JOIN public.standard_params sp ON sp.id=csf.standard_path_id WHERE csf.command_id=ca.id AND csf.deprecated_at IS NULL) paths ON true WHERE c.id=ca.id;


