SELECT c.command_name, c.command_code, 'MML', c.command_name, CASE WHEN c.operation_type='MOD' THEN 'SetParameterValues' ELSE 'GetParameterValues' END, c.operation_type, '[]'::jsonb, '[]'::jsonb, g.id, jsonb_build_object('zh-CN', c.command_name, 'en-US', c.command_code), jsonb_build_object('zh-CN', c.logical_name, 'en-US', c.command_code), 'standard', true, '' FROM cmd_defs c CROSS JOIN target_group g
