INSERT INTO public.mml_command_sub_fields (command_id, mml_code, label_i18n, default_selected, is_required, sort_order, standard_path_id, access_type, is_supported)
SELECT c.id, w.mml_code, jsonb_build_object('zh-CN', w.label_zh, 'en-US', w.mml_code), true, c.operation_type='MOD', w.sort_order, sp.id, CASE WHEN sp.access='READ_WRITE' THEN 'RW' ELSE 'RO' END, true FROM wanted w JOIN public.mml_commands c ON c.command_code=w.command_code JOIN public.standard_params sp ON sp.standard_path=w.standard_path
ON CONFLICT (command_id, standard_path_id) DO UPDATE SET deprecated_at=NULL, mml_code=EXCLUDED.mml_code, label_i18n=EXCLUDED.label_i18n, default_selected=EXCLUDED.default_selected, is_required=EXCLUDED.is_required, sort_order=EXCLUDED.sort_order, access_type=EXCLUDED.access_type, is_supported=EXCLUDED.is_supported, updated_at=now();

WITH canonical AS (SELECT id FROM public.mml_commands WHERE command_code IN (
  'LST SF_NR_SJ_SUB_01',
  'MOD SF_NR_SJ_SUB_01',
  'LST SF_NR_SJ_SUB_02',
  'MOD SF_NR_SJ_SUB_02',
